/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

//BLAS PARAMS
//SIDE = 'L'
//UPLO = 'L'
// =>  Form  C := alpha*A*B + beta*C
// A is MxM
// B is MxN
// C is MxN
//note that due to Fortran array layout, the code below more closely resembles upper triangular case in BLAS
#pragma scop

  /* 
   * Optimization: Cache Blocking (Tiling)
   * The original loop structure computes C = beta*C + alpha*A*B where A is symmetric.
   * To improve cache locality, we tile the loops into blocks of size BLK_I, BLK_J, and BLK_K.
   * We rearrange the loops to (ii, jj, kk) so that a block of C is kept in L1/L2 cache 
   * while blocks of A and B are efficiently streamed.
   * Because A is symmetric and only the lower triangle is provided, A_symm[i][k] is:
   *   A[i][k] if k < i
   *   A[i][i] if k == i
   *   A[k][i] if k > i
   * We split the k loop into these three segments to completely avoid conditionals inside innermost logic.
   */
  int BLK_I = 128;
  int BLK_J = 256;
  int BLK_K = 128;

  for (int ii = 0; ii < _PB_M; ii += BLK_I) {
      for (int jj = 0; jj < _PB_N; jj += BLK_J) {

          int i_end = (ii + BLK_I < _PB_M) ? ii + BLK_I : _PB_M;
          int j_end = (jj + BLK_J < _PB_N) ? jj + BLK_J : _PB_N;

          // First, apply beta to the current block of C
          for (i = ii; i < i_end; i++) {
              #pragma GCC ivdep
              for (j = jj; j < j_end; j++) {
                  C[i][j] *= beta;
              }
          }

          // Then, correctly accumulate the alpha*A*B dot products onto it
          for (int kk = 0; kk < _PB_M; kk += BLK_K) {
              int k_end = (kk + BLK_K < _PB_M) ? kk + BLK_K : _PB_M;

              for (i = ii; i < i_end; i++) {

                  // Segment 1: k < i -> Read from Lower Triangle directly -> Use A[i][k]
                  int k_limit1 = (k_end < i) ? k_end : i;
                  for (k = kk; k < k_limit1; k++) {
                      DATA_TYPE aik = alpha * A[i][k];
                      #pragma GCC ivdep
                      for (j = jj; j < j_end; j++) {
                          C[i][j] += aik * B[k][j];
                      }
                  }

                  // Segment 2: k == i -> Read Diagonal -> Use A[i][i]
                  if (kk <= i && i < k_end) {
                      DATA_TYPE aii = alpha * A[i][i];
                      #pragma GCC ivdep
                      for (j = jj; j < j_end; j++) {
                          C[i][j] += aii * B[i][j];
                      }
                  }

                  // Segment 3: k > i -> Rely on symmetry, access Lower Triangle safely -> Use A[k][i]
                  int k_start3 = (kk > i + 1) ? kk : (i + 1);
                  for (k = k_start3; k < k_end; k++) {
                      DATA_TYPE aki = alpha * A[k][i];
                      #pragma GCC ivdep
                      for (j = jj; j < j_end; j++) {
                          C[i][j] += aki * B[k][j];
                      }
                  }
              }
          }
      }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_symm (m, n,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
