// Structure to pass chunk parameters to worker threads
typedef struct {
    int start_i;
    int end_i;
    int m;
    int n;
    DATA_TYPE alpha;
    DATA_TYPE beta;
    void * C;
    const void * A;
    const void * B;
} ThreadData;

// Thread worker mapping loop computations to assigned ranges safely without data races
static int worker_thread(void* arg) {
    ThreadData* td = (ThreadData*)arg;
    int start_i = td->start_i;
    int end_i = td->end_i;
    int m = td->m;
    int n = td->n;
    DATA_TYPE alpha = td->alpha;
    DATA_TYPE beta = td->beta;

    // Using strict pointers explicitly defining matrix scopes and constraints
    DATA_TYPE (*C)[n] = (DATA_TYPE (*)[n])td->C;
    const DATA_TYPE (*A)[m] = (const DATA_TYPE (*)[m])td->A;
    const DATA_TYPE (*B)[n] = (const DATA_TYPE (*)[n])td->B;

    // Cache blocking factors ensuring subset operations comfortably fit CPU L1/L2 Cache bounds
    int BI = 64;
    int BJ = 256;
    int BK = 64;

    for (int ii = start_i; ii < end_i; ii += BI) {
        int i_end = (ii + BI < end_i) ? ii + BI : end_i;

        for (int jj = 0; jj < n; jj += BJ) {
            int j_end = (jj + BJ < n) ? jj + BJ : n;

            // Phase 1: Apply 'beta' weight initializing the respective C tile
            for (int i = ii; i < i_end; i++) {
                DATA_TYPE* restrict C_row = C[i];
                #pragma GCC ivdep
                for (int j = jj; j < j_end; j++) {
                    C_row[j] *= beta;
                }
            }

            // Phase 2: Accumulate fully resolving computations against corresponding A, B tiles
            for (int kk = 0; kk < m; kk += BK) {
                int k_end = (kk + BK < m) ? kk + BK : m;

                for (int i = ii; i < i_end; i++) {
                    DATA_TYPE* restrict C_row = C[i];

                    int k = kk;
                    // Unroll 'k' factor to fully maximize FMA instruction-level parallelism interleaving
                    for (; k <= k_end - 4; k += 4) {
                        DATA_TYPE a_alpha0 = alpha * ((k <= i) ? A[i][k] : A[k][i]);
                        DATA_TYPE a_alpha1 = alpha * ((k + 1 <= i) ? A[i][k + 1] : A[k + 1][i]);
                        DATA_TYPE a_alpha2 = alpha * ((k + 2 <= i) ? A[i][k + 2] : A[k + 2][i]);
                        DATA_TYPE a_alpha3 = alpha * ((k + 3 <= i) ? A[i][k + 3] : A[k + 3][i]);

                        const DATA_TYPE* restrict B_row0 = B[k];
                        const DATA_TYPE* restrict B_row1 = B[k + 1];
                        const DATA_TYPE* restrict B_row2 = B[k + 2];
                        const DATA_TYPE* restrict B_row3 = B[k + 3];

                        #pragma GCC ivdep
                        for (int j = jj; j < j_end; j++) {
                            C_row[j] += a_alpha0 * B_row0[j] 
                                      + a_alpha1 * B_row1[j] 
                                      + a_alpha2 * B_row2[j] 
                                      + a_alpha3 * B_row3[j];
                        }
                    }
                    // Handle edge cases remainder mapping
